#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<string> inputs;
    string line;
    getline(cin, line);
    istringstream iss(line);
    string token;
    while (iss >> token) {
        inputs.push_back(token);
    }
    int a, b;
    vector<int> nums;
    for (const auto& s : inputs) {
        nums.push_back(stoi(s));
    }
    sort(nums.begin(), nums.end());
    a = nums[0];
    b = nums[1];

    int res;
    if (a == 1 || a == 2) {
        if (a == 1) {
            res = a * b - min(b % 6, 6 - b % 6);
        } else { // a == 2
            res = a * b - (2 * (b == 3 || b == 7) + 4 * (b == 2));
        }
    } else {
        res = a * b - (a & 1) * (b & 1);
    }
    cout << res << "\n";
    return 0;
}

